import java.util.NoSuchElementException;

class IntLinkedList {
    private static class Node {
        int value;
        Node next;
        Node(int value, Node next) { this.value = value; this.next = next; }
    }

    private Node head, tail;
    private int size;

    void addFirst(int value) {
        head = new Node(value, head);
        if (tail == null) tail = head;
        size++;
    }

    void addLast(int value) {
        Node n = new Node(value, null);
        if (tail == null) head = tail = n;
        else { tail.next = n; tail = n; }
        size++;
    }

    int removeFirst() {
        if (head == null) throw new NoSuchElementException("empty list");
        int v = head.value;
        head = head.next;
        if (head == null) tail = null;
        size--;
        return v;
    }

    int get(int index) {
        if (index < 0 || index >= size) throw new IndexOutOfBoundsException("index " + index);
        Node n = head;
        for (int i = 0; i < index; i++) n = n.next;
        return n.value;
    }

    int indexOf(int value) {
        int i = 0;
        for (Node n = head; n != null; n = n.next, i++) if (n.value == value) return i;
        return -1;
    }

    int removeAll(int value) {
        int removed = 0;
        while (head != null && head.value == value) { head = head.next; removed++; }
        Node prev = head;
        while (prev != null && prev.next != null) {
            if (prev.next.value == value) { prev.next = prev.next.next; removed++; }
            else prev = prev.next;
        }
        tail = prev;
        if (head == null) tail = null;
        size -= removed;
        return removed;
    }

    void reverse() {
        Node prev = null, cur = head;
        tail = head;
        while (cur != null) {
            Node next = cur.next;
            cur.next = prev;
            prev = cur;
            cur = next;
        }
        head = prev;
    }

    int middle() {
        if (head == null) throw new NoSuchElementException("empty list");
        Node slow = head, fast = head;
        while (fast != null && fast.next != null) {
            slow = slow.next;
            fast = fast.next.next;
        }
        return slow.value;
    }

    int size() { return size; }

    @Override
    public String toString() {
        StringBuilder sb = new StringBuilder("[");
        for (Node n = head; n != null; n = n.next) sb.append(n.value).append(n.next != null ? ", " : "");
        return sb.append(']').toString();
    }
}

unitTests:
Function<int[], IntLinkedList> of = values -> {
    IntLinkedList l = new IntLinkedList();
    for (int v : values) l.addLast(v);
    return l;
};

test("adding and reading", () -> {
    IntLinkedList l = new IntLinkedList();
    l.addLast(2); l.addFirst(1); l.addLast(3);
    checkEq(l.toString(), "[1, 2, 3]");
    checkEq(l.size(), 3);
    checkEq(l.get(2), 3);
    checkEq(l.indexOf(2), 1);
    checkEq(l.indexOf(9), -1);
    checkThrows(IndexOutOfBoundsException.class, () -> l.get(3));
    checkEq(new IntLinkedList().toString(), "[]");
});

test("removing from the front", () -> {
    IntLinkedList l = of.apply(new int[] {7, 8});
    checkEq(l.removeFirst(), 7);
    checkEq(l.removeFirst(), 8);
    checkThrows(NoSuchElementException.class, l::removeFirst);
    l.addLast(5);
    checkEq(l.toString(), "[5]");
});

test("removing every match", () -> {
    IntLinkedList l = of.apply(new int[] {1, 1, 2, 1, 3, 1});
    checkEq(l.removeAll(1), 4);
    checkEq(l.toString(), "[2, 3]");
    l.addLast(4);
    checkEq(l.toString(), "[2, 3, 4]");
    checkEq(l.size(), 3);
    IntLinkedList all = of.apply(new int[] {9, 9});
    checkEq(all.removeAll(9), 2);
    all.addLast(1);
    checkEq(all.toString(), "[1]");
});

test("reversing and the middle", () -> {
    IntLinkedList l = of.apply(new int[] {1, 2, 3, 4, 5});
    checkEq(l.middle(), 3);
    l.reverse();
    checkEq(l.toString(), "[5, 4, 3, 2, 1]");
    l.addLast(0);
    checkEq(l.toString(), "[5, 4, 3, 2, 1, 0]");
    checkEq(l.middle(), 2);
    IntLinkedList one = of.apply(new int[] {42});
    one.reverse();
    checkEq(one.toString() + one.middle(), "[42]42");
});

